<style>
  :root{--brand:#ff5a1f;--brand-soft:#ff8a55;--ink:#f4f6fa;--muted:#a3acbb;--line:rgba(255,255,255,.12);--glass:rgba(12,15,21,.55)}
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;background:#0b0d12;color:var(--ink);font-family:'Plus Jakarta Sans',system-ui,sans-serif;overflow:hidden;-webkit-font-smoothing:antialiased}
  #scene{position:fixed;inset:0;display:block;width:100%;height:100%;cursor:grab;touch-action:none}
  #scene.dragging{cursor:grabbing}
  .vignette{position:fixed;inset:0;pointer-events:none;background:
     radial-gradient(120% 80% at 50% 40%,transparent 55%,rgba(5,6,9,.55) 100%),
     linear-gradient(180deg,rgba(5,6,9,.35) 0%,transparent 22%,transparent 55%,rgba(5,6,9,.78) 100%)}
  header{position:fixed;top:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:calc(18px + env(safe-area-inset-top)) clamp(18px,4vw,44px) 0;pointer-events:none}
  .brand{display:flex;align-items:center;gap:14px}
  .brand img{width:56px;height:56px;border-radius:50%;filter:drop-shadow(0 6px 18px rgba(0,0,0,.5))}
  .brand b{display:block;font-weight:800;letter-spacing:.3px;font-size:17px}
  .brand span{display:block;color:var(--muted);font-size:13px;margin-top:2px}
  .chip{pointer-events:auto;display:inline-flex;align-items:center;gap:9px;padding:9px 14px;border-radius:999px;background:var(--glass);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:inset 0 0 0 1px var(--line);font:700 11px/1 'JetBrains Mono',monospace;letter-spacing:1.6px;color:var(--brand-soft);text-transform:uppercase}
  .chip i{width:8px;height:8px;border-radius:50%;background:var(--brand);box-shadow:0 0 12px var(--brand);animation:blink 1.6s infinite}
  @keyframes blink{50%{opacity:.25}}

  main{position:fixed;left:50%;bottom:calc(26px + env(safe-area-inset-bottom));transform:translateX(-50%);width:min(620px,calc(100% - 32px));pointer-events:none}
  .card{pointer-events:auto;padding:26px 28px 24px;border-radius:28px;background:var(--glass);backdrop-filter:blur(16px) saturate(140%);-webkit-backdrop-filter:blur(16px) saturate(140%);box-shadow:inset 0 0 0 1px var(--line),0 30px 80px rgba(0,0,0,.45);opacity:0;transform:translateY(24px);animation:rise 1s .5s cubic-bezier(.2,.8,.2,1) forwards}
  @keyframes rise{to{opacity:1;transform:none}}
  .eyebrow{font:700 11px/1 'JetBrains Mono',monospace;letter-spacing:2px;color:var(--brand-soft);text-transform:uppercase}
  h1{font-weight:800;font-size:clamp(26px,4.4vw,38px);line-height:1.08;letter-spacing:-.6px;margin-top:10px}
  h1 em{font-style:normal;color:var(--brand)}
  .lead{color:var(--muted);font-size:15px;line-height:1.55;margin-top:10px}
  .progress-head{display:flex;justify-content:space-between;align-items:flex-end;margin-top:22px}
  .progress-head span{font:600 12px/1 'JetBrains Mono',monospace;letter-spacing:1.4px;color:var(--muted);text-transform:uppercase}
  .pct{font:800 40px/1 'Plus Jakarta Sans',sans-serif;letter-spacing:-1px;font-variant-numeric:tabular-nums}
  .pct small{font-size:20px;color:var(--brand)}
  .bar{position:relative;height:14px;margin-top:12px;border-radius:999px;background:rgba(255,255,255,.08);box-shadow:inset 0 0 0 1px var(--line);overflow:hidden}
  .fill{position:absolute;inset:0 auto 0 0;width:0;border-radius:inherit;background:linear-gradient(90deg,#ff3d00,var(--brand) 55%,#ffb37f);box-shadow:0 0 24px rgba(255,90,31,.65);transition:width 2.6s cubic-bezier(.16,.84,.24,1)}
  .fill::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.55) 48%,transparent 66%);background-size:220% 100%;animation:shine 2.4s linear infinite;border-radius:inherit}
  @keyframes shine{from{background-position:160% 0}to{background-position:-60% 0}}
  .ticks{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 calc(10% - 1px),rgba(255,255,255,.14) calc(10% - 1px) 10%)}
  .tasks{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:8px 18px;margin-top:18px}
  .tasks li{display:flex;align-items:center;gap:10px;font-size:13.5px;color:#d6dbe4;opacity:0;transform:translateY(6px);animation:rise .6s forwards}
  .tasks li .dot{flex:none;width:18px;height:18px;border-radius:50%;display:grid;place-items:center;background:rgba(61,220,151,.14);box-shadow:inset 0 0 0 1px rgba(61,220,151,.5);color:#3ddc97;font-size:11px;font-weight:800}
  .tasks li.wip .dot{background:rgba(255,90,31,.15);box-shadow:inset 0 0 0 1px rgba(255,90,31,.6)}
  .tasks li.wip .dot::before{content:"";width:8px;height:8px;border-radius:50%;border:2px solid var(--brand);border-right-color:transparent;animation:spin .9s linear infinite}
  .tasks li.wip{color:#fff;font-weight:600}
  @keyframes spin{to{transform:rotate(360deg)}}
  .foot{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:20px;padding-top:16px;border-top:1px solid var(--line);font-size:12.5px;color:var(--muted)}
  .foot b{color:var(--ink)}
  .credit{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:14px;padding:10px 14px;border-radius:14px;background:rgba(255,255,255,.04);box-shadow:inset 0 0 0 1px var(--line);color:var(--muted);font-size:12px;text-decoration:none;transition:background .2s,box-shadow .2s}
  .credit:hover{background:rgba(255,255,255,.08);box-shadow:inset 0 0 0 1px rgba(255,255,255,.22)}
  .credit img{height:15px;width:auto;opacity:.95}
  .credit .url{font:700 11.5px/1 'JetBrains Mono',monospace;letter-spacing:.5px;color:var(--ink)}
  .hint{display:inline-flex;align-items:center;gap:8px;font:600 11px/1 'JetBrains Mono',monospace;letter-spacing:1px;text-transform:uppercase;color:#8a93a3}
  .hint svg{width:16px;height:16px}
  .alt{position:fixed;pointer-events:none;font:700 11px/1 'JetBrains Mono',monospace;letter-spacing:1.5px;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.6);white-space:nowrap;transform:translate(-50%,-140%);opacity:0;transition:opacity .6s}
  .alt::after{content:"";display:block;width:1px;height:26px;margin:8px auto 0;background:linear-gradient(#fff,transparent)}
  .alt span{color:var(--brand-soft)}
  @media (max-width:640px){
    .tasks{display:none}
    h1{font-size:25px}
    .lead{font-size:13.5px;line-height:1.5}
    .brand img{width:40px;height:40px}.brand b{font-size:15px}.brand span{font-size:12px}
    header .chip{display:none}
    .card{padding:20px 20px 18px;border-radius:24px}
    .lead{font-size:14px}
    .tasks{grid-template-columns:1fr;gap:7px}
    .pct{font-size:34px}
    .foot{flex-direction:column;align-items:flex-start}
  }
  @media (max-height:760px) and (min-width:641px){.tasks{display:none}}
  @media (prefers-reduced-motion:reduce){.fill{transition:none}.fill::after,.chip i{animation:none}}
  noscript{position:fixed;inset:0;display:grid;place-items:center;background:#0b0d12}
</style>
