<script>
  // Progress bar → 90%
  const TARGET = 90;
  requestAnimationFrame(()=>setTimeout(()=>{document.getElementById('fill').style.width = TARGET + '%';},700));
  (function count(){const el=document.getElementById('pctNum');const t0=performance.now()+700,d=2600;
    (function step(now){const p=Math.min(1,Math.max(0,(now-t0)/d));const e=1-Math.pow(1-p,4);el.textContent=Math.round(e*TARGET);if(p<1)requestAnimationFrame(step);})(performance.now());})();
</script>

<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js"}}</script>
<script type="module">
import * as THREE from 'three';

const canvas = document.getElementById('scene');
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.98;
renderer.outputColorSpace = THREE.SRGBColorSpace;

const scene = new THREE.Scene();
const FOG = new THREE.Color('#7a6278');
scene.fog = new THREE.FogExp2(FOG, 0.00072);

const camera = new THREE.PerspectiveCamera(42, 1, 1, 4000);

// ---------- Noise ----------
function hash(x,y){const s=Math.sin(x*127.1+y*311.7)*43758.5453;return s-Math.floor(s);}
function vnoise(x,y){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi;
  const u=xf*xf*(3-2*xf),v=yf*yf*(3-2*yf);
  const a=hash(xi,yi),b=hash(xi+1,yi),c=hash(xi,yi+1),d=hash(xi+1,yi+1);
  return a+(b-a)*u+(c-a)*v+(a-b-c+d)*u*v;}
function fbm(x,y,o=5){let s=0,a=.5,f=1;for(let i=0;i<o;i++){s+=a*vnoise(x*f,y*f);f*=2.03;a*=.5;}return s;}
function ridged(x,y,o=5){let s=0,a=.5,f=1;for(let i=0;i<o;i++){let n=1-Math.abs(vnoise(x*f,y*f)*2-1);s+=a*n*n;f*=2.1;a*=.5;}return s;}

// ---------- Mountain (Cikuray: steep, near-symmetric stratovolcano cone) ----------
const PEAK = 235, R = 360;
function heightAt(x,z){
  const r = Math.hypot(x,z), th = Math.atan2(z,x);
  const t = Math.max(0, 1 - r/R);
  let cone = Math.pow(t, 1.55) * PEAK;                 // concave cone profile
  const summit = Math.exp(-Math.pow(r/26,2));           // slightly rounded summit
  cone = cone*(1-summit*0.06);
  // radial erosion gullies (barrancos) typical of stratovolcano flanks
  const warp = fbm(x*.012+3, z*.012-7, 3)*2.4;
  const gul = Math.pow(Math.abs(Math.sin(th*13 + warp + r*.006)), .6);
  const gullyDepth = (1-gul) * 13 * Math.sin(Math.min(1,t*1.6)*Math.PI*.9) * Math.min(1,r/40);
  const rough = (ridged(x*.02, z*.02, 5)-.45) * 14 * (0.35 + t);
  // foothills / surrounding terrain
  const hills = fbm(x*.006+11, z*.006+5, 5) * 46 - 10;
  const base = Math.max(hills * Math.min(1, r/(R*.9)), 0);
  return Math.max(cone - gullyDepth + rough*Math.min(1,t*3), base + rough*.25) - 6;
}

const SIZE = 1500, SEG = innerWidth < 700 ? 230 : 340;
const geo = new THREE.PlaneGeometry(SIZE, SIZE, SEG, SEG);
geo.rotateX(-Math.PI/2);
const pos = geo.attributes.position;
for (let i=0;i<pos.count;i++){ const x=pos.getX(i), z=pos.getZ(i); pos.setY(i, heightAt(x,z)); }
geo.computeVertexNormals();
// vertex colors: lowland forest → montane forest → shrub → bare volcanic summit
const col = new Float32Array(pos.count*3), nrm = geo.attributes.normal, c = new THREE.Color();
const cForest=new THREE.Color('#2a4d2e'), cMont=new THREE.Color('#3f6236'), cShrub=new THREE.Color('#6b6a3e'), cRock=new THREE.Color('#5a4a3f'), cTop=new THREE.Color('#8b7a6a');
for (let i=0;i<pos.count;i++){
  const y=pos.getY(i), slope=1-nrm.getY(i), h=y/PEAK;
  const n=fbm(pos.getX(i)*.05,pos.getZ(i)*.05,3);
  if (h<.55) c.copy(cForest).lerp(cMont, THREE.MathUtils.smoothstep(h,.15,.55));
  else if (h<.82) c.copy(cMont).lerp(cShrub, THREE.MathUtils.smoothstep(h,.55,.82));
  else c.copy(cShrub).lerp(cRock, THREE.MathUtils.smoothstep(h,.82,.93));
  if (h>.93) c.lerp(cTop, THREE.MathUtils.smoothstep(h,.93,1));
  c.lerp(cRock, THREE.MathUtils.clamp(slope*1.6-.35,0,.6));
  c.multiplyScalar(.82+n*.36);
  col.set([c.r,c.g,c.b], i*3);
}
geo.setAttribute('color', new THREE.BufferAttribute(col,3));
const terrain = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({vertexColors:true, roughness:.95, metalness:0, flatShading:false}));
scene.add(terrain);

// summit beacon (pos puncak)
const summitY = heightAt(0,0);
const beacon = new THREE.Mesh(new THREE.SphereGeometry(1.6,16,16), new THREE.MeshBasicMaterial({color:'#ff7a3d'}));
beacon.position.set(0, summitY+2.2, 0); scene.add(beacon);
const glowTex = (()=>{const cv=document.createElement('canvas');cv.width=cv.height=128;const g=cv.getContext('2d');const gr=g.createRadialGradient(64,64,0,64,64,64);gr.addColorStop(0,'rgba(255,255,255,1)');gr.addColorStop(.25,'rgba(255,200,150,.6)');gr.addColorStop(1,'rgba(255,120,40,0)');g.fillStyle=gr;g.fillRect(0,0,128,128);return new THREE.CanvasTexture(cv);})();
const beaconGlow = new THREE.Sprite(new THREE.SpriteMaterial({map:glowTex, color:'#ff6a2a', blending:THREE.AdditiveBlending, depthWrite:false, transparent:true}));
beaconGlow.scale.set(26,26,1); beaconGlow.position.copy(beacon.position); scene.add(beaconGlow);

// ---------- Sky dome (dawn gradient + sun) ----------
const SUN_DIR = new THREE.Vector3(-0.66, 0.16, 0.74).normalize();
const sky = new THREE.Mesh(new THREE.SphereGeometry(2000, 48, 24), new THREE.ShaderMaterial({
  side:THREE.BackSide, depthWrite:false, fog:false,
  uniforms:{uSun:{value:SUN_DIR}, uTime:{value:0}},
  vertexShader:`varying vec3 vDir; void main(){ vDir=normalize(position); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
  fragmentShader:`
    varying vec3 vDir; uniform vec3 uSun; uniform float uTime;
    float h(vec3 p){return fract(sin(dot(p,vec3(12.9898,78.233,37.719)))*43758.5453);}
    void main(){
      float y=clamp(vDir.y,-.2,1.);
      vec3 zen=vec3(.035,.05,.13), mid=vec3(.20,.20,.40), hor=vec3(1.0,.52,.30), low=vec3(.55,.33,.38);
      vec3 col=mix(hor,mid,smoothstep(.0,.22,y));
      col=mix(col,zen,smoothstep(.18,.75,y));
      col=mix(low,col,smoothstep(-.12,.02,y));
      float d=max(dot(normalize(vDir),uSun),0.);
      col+=vec3(1.,.55,.25)*pow(d,10.)*.32 + vec3(1.,.72,.42)*pow(d,90.)*.45 + vec3(1.,.93,.8)*smoothstep(.99935,.99965,d)*1.4;
      // stars toward zenith
      vec3 q=floor(vDir*420.); float s=step(.9965,h(q)); float tw=.6+.4*sin(uTime*2.+h(q+1.)*40.);
      col+=vec3(s*tw)*smoothstep(.25,.7,y)*.9;
      gl_FragColor=vec4(col,1.);
    }`
}));
scene.add(sky);

// ---------- Lights ----------
const sun = new THREE.DirectionalLight('#ffb27a', 3.6);
sun.position.copy(SUN_DIR).multiplyScalar(800); scene.add(sun);
const rim = new THREE.DirectionalLight('#7d8cff', .55); rim.position.set(500,300,600); scene.add(rim);
scene.add(new THREE.HemisphereLight('#9aa2d6', '#3a3628', 1.05));

// ---------- Sea of clouds (layered animated noise shader) ----------
const CLOUD_Y = 70;
const cloudMat = (layer)=> new THREE.ShaderMaterial({
  transparent:true, depthWrite:false, fog:false,
  uniforms:{uTime:{value:0}, uSun:{value:SUN_DIR}, uLayer:{value:layer}, uCam:{value:new THREE.Vector3()}},
  vertexShader:`varying vec3 vW; void main(){ vec4 w=modelMatrix*vec4(position,1.); vW=w.xyz; gl_Position=projectionMatrix*viewMatrix*w; }`,
  fragmentShader:`
    varying vec3 vW; uniform float uTime,uLayer; uniform vec3 uSun,uCam;
    float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
    float noise(vec2 p){vec2 i=floor(p),f=fract(p);vec2 u=f*f*(3.-2.*f);
      return mix(mix(hash(i),hash(i+vec2(1,0)),u.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),u.x),u.y);}
    float fbm(vec2 p){float s=0.,a=.5;mat2 m=mat2(1.6,1.2,-1.2,1.6);for(int i=0;i<6;i++){s+=a*noise(p);p=m*p;a*=.5;}return s;}
    void main(){
      vec2 p=vW.xz*.0042 + vec2(uTime*.010, uTime*.004)*(1.+uLayer*.35) + uLayer*7.3;
      float n=fbm(p + fbm(p*1.7 + uTime*.006)*.9);
      float cov=.40 + uLayer*.05;
      float d=smoothstep(cov, cov+.30, n);
      // thin out around the summit so the peak pokes through cleanly
      float r=length(vW.xz);
      d*=smoothstep(55.,150.,r)*.9+.1;
      // fade at far distance into horizon haze
      float dist=length(vW.xz-uCam.xz);
      float far=smoothstep(1500.,700.,dist);
      // light: warm sunlit tops, cool lavender shadows
      float lit=clamp(n*1.25-.15,0.,1.);
      vec3 shadow=vec3(.42,.43,.62), sunlit=vec3(1.,.80,.66);
      vec3 col=mix(shadow,sunlit,lit);
      vec2 sd=normalize(uSun.xz); float toward=dot(normalize(vW.xz-uCam.xz),sd);
      col+=vec3(1.,.55,.3)*pow(max(toward,0.),6.)*.35;
      float a=d*(.70-uLayer*.14)*far;
      gl_FragColor=vec4(col,a);
    }`
});
const cloudLayers=[];
for (let i=0;i<3;i++){
  const m=new THREE.Mesh(new THREE.PlaneGeometry(3200,3200,1,1), cloudMat(i));
  m.rotation.x=-Math.PI/2; m.position.y=CLOUD_Y + i*9; m.renderOrder=2+i;
  scene.add(m); cloudLayers.push(m);
}
// soft billowy puffs hugging the slopes for depth
const puffTex=(()=>{const cv=document.createElement('canvas');cv.width=cv.height=256;const g=cv.getContext('2d');
  for(let k=0;k<22;k++){const x=96+Math.random()*64,y=110+Math.random()*36,r=24+Math.random()*30;const gr=g.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,'rgba(255,255,255,.55)');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(0,0,256,256);}
  const t=new THREE.CanvasTexture(cv);t.colorSpace=THREE.SRGBColorSpace;return t;})();
const puffs=new THREE.Group(); scene.add(puffs);
for(let i=0;i<70;i++){
  const a=Math.random()*Math.PI*2, r=110+Math.random()*420;
  const s=new THREE.Sprite(new THREE.SpriteMaterial({map:puffTex, transparent:true, depthWrite:false, fog:false, opacity:.26+Math.random()*.22, color:new THREE.Color().setHSL(.04+Math.random()*.05,.45,.86)}));
  const sc=140+Math.random()*180; s.scale.set(sc,sc*.42,1);
  s.position.set(Math.cos(a)*r, CLOUD_Y+4+Math.random()*16, Math.sin(a)*r);
  s.userData={a,r,sp:(Math.random()*.5+.5)*.012*(Math.random()<.5?-1:1), y0:s.position.y, ph:Math.random()*6};
  puffs.add(s);
}

// birds? keep it calm: drifting particles (dust / fireflies near summit)
const pCount=240, pGeo=new THREE.BufferGeometry(), pArr=new Float32Array(pCount*3);
for(let i=0;i<pCount;i++){const a=Math.random()*6.28,r=Math.random()*300;pArr.set([Math.cos(a)*r, CLOUD_Y+20+Math.random()*160, Math.sin(a)*r],i*3);}
pGeo.setAttribute('position',new THREE.BufferAttribute(pArr,3));
const motes=new THREE.Points(pGeo,new THREE.PointsMaterial({size:1.1,color:'#ffd2b0',transparent:true,opacity:.28,depthWrite:false,blending:THREE.AdditiveBlending}));
scene.add(motes);

// ---------- Camera orbit (drag / touch / wheel / parallax) ----------
const target = new THREE.Vector3(0, 95, 0);
let az = 0.55, el = 0.08, dist = 560;          // current
let tAz = az, tEl = el, tDist = dist;           // targets
let dragging=false, lastX=0, lastY=0, idle=0, px=0, py=0;
const isMobile = () => innerWidth < 700;
canvas.addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');idle=0;});
addEventListener('pointerup',()=>{dragging=false;canvas.classList.remove('dragging');});
addEventListener('pointermove',e=>{
  px=(e.clientX/innerWidth-.5)*2; py=(e.clientY/innerHeight-.5)*2;
  if(!dragging) return;
  tAz -= (e.clientX-lastX)*0.005; tEl = THREE.MathUtils.clamp(tEl + (e.clientY-lastY)*0.003, 0.0, 0.5);
  lastX=e.clientX; lastY=e.clientY; idle=0;
});
canvas.addEventListener('wheel',e=>{e.preventDefault();tDist=THREE.MathUtils.clamp(tDist*(1+Math.sign(e.deltaY)*.08),300,820);idle=0;},{passive:false});
let pinch=0;
canvas.addEventListener('touchmove',e=>{if(e.touches.length===2){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);if(pinch)tDist=THREE.MathUtils.clamp(tDist*(pinch/d),300,820);pinch=d;}},{passive:true});
canvas.addEventListener('touchend',()=>pinch=0);
addEventListener('keydown',e=>{if(e.key==='ArrowLeft')tAz+=.15;if(e.key==='ArrowRight')tAz-=.15;});

function resize(){
  const w=innerWidth,h=innerHeight, portrait=w/h<.8; renderer.setSize(w,h,false); camera.aspect=w/h;
  camera.fov = portrait ? 52 : 40;
  target.y = 120;
  if (portrait) tDist = Math.max(tDist, 760);
  // shift the rendered view so the peak sits in the upper part of the screen, clear of the info card
  const shift = portrait ? .20 : (h < 820 ? .15 : .11);
  camera.setViewOffset(w, h, 0, h*shift, w, h);
  camera.updateProjectionMatrix();
}
addEventListener('resize',resize); resize();

const peakLabel=document.getElementById('peakLabel'), v3=new THREE.Vector3();
const clock=new THREE.Clock(); let t=0;
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
function frame(){
  const dt=Math.min(clock.getDelta(),.05); t+=dt; idle+=dt;
  if(!dragging && idle>2.5 && !reduce) tAz += dt*0.045;   // gentle auto-orbit
  az+=(tAz-az)*.06; el+=(tEl-el)*.06; dist+=(tDist-dist)*.06;
  const pAz=az+px*.05, pEl=el-py*.025;
  camera.position.set(target.x+Math.sin(pAz)*Math.cos(pEl)*dist, target.y+Math.sin(pEl)*dist+40, target.z+Math.cos(pAz)*Math.cos(pEl)*dist);
  camera.lookAt(target);

  sky.material.uniforms.uTime.value=t;
  for(const m of cloudLayers){ m.material.uniforms.uTime.value=reduce?0:t; m.material.uniforms.uCam.value.copy(camera.position); }
  for(const s of puffs.children){ const u=s.userData; if(!reduce)u.a+=u.sp*dt; s.position.x=Math.cos(u.a)*u.r; s.position.z=Math.sin(u.a)*u.r; s.position.y=u.y0+Math.sin(t*.4+u.ph)*2; }
  motes.rotation.y = t*.01;
  const pulse=.5+.5*Math.sin(t*3.2); beaconGlow.material.opacity=.45+.55*pulse; beaconGlow.scale.setScalar(20+10*pulse);

  // peak label follows summit
  v3.copy(beacon.position).project(camera);
  const visible=v3.z<1 && Math.abs(v3.x)<1 && Math.abs(v3.y)<1;
  peakLabel.style.left=((v3.x*.5+.5)*innerWidth)+'px'; peakLabel.style.top=((-v3.y*.5+.5)*innerHeight)+'px';
  peakLabel.style.opacity = visible && t>1.5 ? 1 : 0;

  renderer.render(scene,camera);
  requestAnimationFrame(frame);
}
frame();
</script>
</body>
</html>

@endverbatim
